#include <stdio.h>

static int sum_less_than(long long t, long long a, long long limit) {
    __int128 sum = (__int128)t * (2 * (__int128)a + t - 1) / 2;
    return sum < limit;
}

int main(void) {
    int p;
    scanf("%d", &p);

    while (p--) {
        long long l, a, b;
        scanf("%lld %lld %lld", &l, &a, &b);

        long long n = b - a + 1;
        long long lo = 0, hi = n;

        while (hi - lo > 1) {
            long long mid = lo + (hi - lo) / 2;
            if (sum_less_than(mid, a, l))
                lo = mid;
            else
                hi = mid;
        }

        printf("%lld\n", lo + 1);
    }

    return 0;
}
